import { screen } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import { renderWithProviders } from "../../../tests/utils";
import { ConversationEventType, type ConversationEvent } from "../../../types";
import { FlowEvent } from "./FlowEvent";

function makeEvent(
  flowId: string,
  eventType: ConversationEventType = ConversationEventType.FlowStarted,
): ConversationEvent {
  return {
    __typename: "ConversationEvent",
    id: "1",
    conversationEventType: eventType,
    name: "flow_started",
    actionText: "",
    flowId,
    slotValue: null,
    stepId: "",
    timestamp: new Date().toISOString(),
    originalTimestamp: 0,
    metadata: { parseData: {} },
  };
}

describe("FlowEvent naming", () => {
  it("labels a user flow", () => {
    renderWithProviders(<FlowEvent event={makeEvent("transfer_money")} isSelected={false} />);
    expect(screen.getByText(/^Flow/)).toBeInTheDocument();
  });

  it("labels pattern flows as system flows", () => {
    renderWithProviders(
      <FlowEvent event={makeEvent("pattern_continue_interrupted")} isSelected={false} />,
    );
    expect(screen.getByText(/^System flow/)).toBeInTheDocument();
  });

  it("does not retarget flow_* rows when a skill catalog is present", () => {
    renderWithProviders(<FlowEvent event={makeEvent("travel_notice")} isSelected={false} />, {
      initialStoreState: { skillCatalog: {} },
    });
    expect(screen.getByText(/^Flow/)).toBeInTheDocument();
    expect(screen.queryByText(/^Skill/)).not.toBeInTheDocument();
  });

  it("labels compiled ordered-block ids as Flow", () => {
    renderWithProviders(
      <FlowEvent event={makeEvent("travel_notice__submit")} isSelected={false} />,
      { initialStoreState: { skillCatalog: {} } },
    );
    expect(screen.getByText(/^Flow/)).toBeInTheDocument();
    expect(screen.queryByText(/^Block/)).not.toBeInTheDocument();
  });

  it("labels engine-managed default_* ids as Flow", () => {
    renderWithProviders(
      <FlowEvent event={makeEvent("default_session_start")} isSelected={false} />,
      { initialStoreState: { skillCatalog: {} } },
    );
    expect(screen.getByText(/^Flow/)).toBeInTheDocument();
    expect(screen.queryByText(/System skill/)).not.toBeInTheDocument();
  });

  it("does not infer skill activation from the catalog", () => {
    renderWithProviders(<FlowEvent event={makeEvent("card_replace")} isSelected={false} />, {
      initialStoreState: {
        skillCatalog: {
          card_replace: {
            id: "card_replace",
            name: "Card Replace",
            description: null,
            is_default: false,
            engine_managed: false,
            disabled: false,
            sections: [],
            blocks: {},
            referenced_skills: [],
            tool_names: [],
            hidden: false,
          },
        },
      },
    });

    expect(screen.queryByText("Card Replace")).not.toBeInTheDocument();
    expect(screen.queryByText(/skill activated/)).not.toBeInTheDocument();
    expect(screen.getByText(/^Flow/)).toBeInTheDocument();
  });
});
